// MARK: - Adaptive Helper

extension ColorTokens {
    /// Resolves per trait collection: light/dark from `userInterfaceStyle`,
    /// and the `highContrast` pair (light, dark) when `accessibilityContrast == .high`.
    private static func adaptive(light: UInt, dark: UInt, highContrast: (light: UInt, dark: UInt)? = nil) -> Color {
        #if canImport(UIKit)
        return Color(UIColor { traits in
            let isDark = traits.userInterfaceStyle == .dark
            let hex: UInt
            if let highContrast, traits.accessibilityContrast == .high {
                hex = isDark ? highContrast.dark : highContrast.light
            } else {
                hex = isDark ? dark : light
            }
            return UIColor(
                red: CGFloat((hex >> 16) & 0xFF) / 255,
                green: CGFloat((hex >> 8) & 0xFF) / 255,
                blue: CGFloat(hex & 0xFF) / 255,
                alpha: 1
            )
        })
        #else
        return Color(hex: dark)
        #endif
    }
}

// MARK: - Color Hex Initializer

extension Color {
    init(hex: UInt, opacity: Double = 1.0) {
        let red = Double((hex >> 16) & 0xFF) / 255.0
        let green = Double((hex >> 8) & 0xFF) / 255.0
        let blue = Double(hex & 0xFF) / 255.0
        self.init(.sRGB, red: red, green: green, blue: blue, opacity: opacity)
    }
}
